const INQUIRIES_ADMIN_JS="import{initializeApp}from\"https://www.gstatic.com/firebasejs/12.18.0/firebase-app.js\";import{getAuth,onAuthStateChanged,signOut}from\"https://www.gstatic.com/firebasejs/12.18.0/firebase-auth.js\";import{initializeFirestore,collection,getDocs,doc,updateDoc,deleteDoc,serverTimestamp}from\"https://www.gstatic.com/firebasejs/12.18.0/firebase-firestore.js\";const config={apiKey:\"AIzaSyCh2jJOIPuY64FTP50zMeSN1PbYDHWW1Lo\",authDomain:\"pinstory-26738.firebaseapp.com\",projectId:\"pinstory-26738\",storageBucket:\"pinstory-26738.firebasestorage.app\",messagingSenderId:\"841861837489\",appId:\"1:841861837489:web:1dcf9c86767a8edf762890\"};const app=initializeApp(config),auth=getAuth(app),db=initializeFirestore(app,{experimentalForceLongPolling:true,useFetchStreams:false}),ADMIN=\"cyber924@naver.com\",E=id=>document.getElementById(id);let rows=[],filter=\"all\";function esc(s){return String(s??\"\").replace(/[&<>\"']/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]))}function date(v){return v?.toDate?v.toDate().toLocaleString(\"ko-KR\"):\"\"}async function load(){const snap=await getDocs(collection(db,\"inquiries\"));rows=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0));render()}function render(){E(\"total\").textContent=rows.length;E(\"newCount\").textContent=rows.filter(x=>x.status===\"new\").length;E(\"doneCount\").textContent=rows.filter(x=>x.status===\"done\").length;const show=filter===\"all\"?rows:rows.filter(x=>x.status===filter);E(\"items\").innerHTML=show.length?show.map(x=>`<article class=\"item ${x.status}\"><div class=\"item-head\"><div><h2>${esc(x.subject)}</h2><div class=\"meta\">${esc(x.name)} · ${esc(x.phone)} · ${esc(x.email)} · ${date(x.createdAt)}</div></div><b>${x.status===\"new\"?\"신규\":\"완료\"}</b></div><div class=\"body\">${esc(x.message)}</div><div class=\"actions\">${x.status===\"new\"?`<button class=\"btn dark done\" data-id=\"${x.id}\">처리 완료</button>`:`<button class=\"btn reopen\" data-id=\"${x.id}\">신규로 변경</button>`}<a class=\"btn\" href=\"tel:${esc(x.phone.replace(/[^0-9+]/g,\"\"))}\">전화</a><a class=\"btn\" href=\"mailto:${esc(x.email)}\">이메일</a><button class=\"btn danger del\" data-id=\"${x.id}\">삭제</button></div></article>`).join(\"\"):'<p class=\"empty\">해당 문의가 없습니다.</p>';document.querySelectorAll(\".done\").forEach(b=>b.onclick=()=>status(b.dataset.id,\"done\"));document.querySelectorAll(\".reopen\").forEach(b=>b.onclick=()=>status(b.dataset.id,\"new\"));document.querySelectorAll(\".del\").forEach(b=>b.onclick=()=>remove(b.dataset.id))}async function status(id,value){await updateDoc(doc(db,\"inquiries\",id),{status:value,updatedAt:serverTimestamp()});await load()}async function remove(id){if(!confirm(\"이 문의를 삭제할까요?\"))return;await deleteDoc(doc(db,\"inquiries\",id));await load()}document.querySelectorAll(\".filter\").forEach(b=>b.onclick=()=>{filter=b.dataset.status;render()});E(\"logout\").onclick=async()=>{await signOut(auth);location.href=\"/login\"};onAuthStateChanged(auth,async user=>{if(!user||(user.email||\"\").toLowerCase()!==ADMIN){location.replace(\"/login\");return}E(\"user\").textContent=user.email;try{await load()}catch(error){E(\"items\").innerHTML='<p class=\"error\">'+esc(error.message)+'</p>'}});\n";
