const DETAIL_CSS='.detail-head{padding:52px 6% 42px;text-align:center;background:linear-gradient(135deg,#fff,#f8fbfd);border-bottom:1px solid var(--line)}.detail-head h1{max-width:820px;margin:12px auto;font-size:38px;line-height:1.35}.detail-head p{max-width:760px;margin:15px auto 0;background:#fff;border:1px solid var(--line);border-radius:14px;padding:18px;color:#577180;line-height:1.7}.detail-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:28px;align-items:start}.detail-layout .article{margin-top:30px}.article-body{white-space:normal}.article-body p{margin:0 0 20px}.section-title{font-size:25px;margin:42px 0 15px;padding-bottom:10px;border-bottom:2px solid #e2edf2}.section-subtitle{font-size:19px;margin:28px 0 12px}.article-point{background:#f2f8fb;border-left:4px solid #18a9d2;padding:13px 16px;margin:9px 0;border-radius:6px}.latest{margin-top:30px;background:#fff;border:1px solid var(--line);border-radius:15px;padding:18px;position:sticky;top:92px}.latest h2{font-size:17px;margin:0 0 12px}.latest-item{display:grid;grid-template-columns:72px 1fr;gap:10px;padding:11px 0;border-top:1px solid #edf2f5}.latest-item img{width:72px;height:58px;object-fit:cover;border-radius:8px}.latest-item b{display:block;font-size:12px;line-height:1.4}.latest-item small{display:block;color:#8aa0ac;margin-top:5px}.article-cta{margin-top:42px;background:#052f45;color:#fff;border-radius:14px;padding:24px}.article-cta b{font-size:20px}.article-cta a{display:inline-block;background:var(--cyan);color:#062f45;font-weight:900;padding:10px 16px;border-radius:8px}@media(max-width:850px){.detail-layout{grid-template-columns:1fr}.latest{position:static}.detail-head h1{font-size:29px}}';
const MOBILE_CSS='.mobile-toggle{display:none;margin-left:auto;border:1px solid #d8e4eb;background:#fff;border-radius:8px;padding:8px 11px;font-size:19px;line-height:1;cursor:pointer}@media(max-width:760px){body{overflow-x:hidden}header .mobile-toggle,.top .mobile-toggle{display:block!important}header .nav,.top .nav{display:none!important;position:absolute!important;left:12px!important;right:12px!important;top:64px!important;width:auto!important;max-height:70vh!important;overflow:auto!important;flex-direction:column!important;gap:0!important;background:#fff!important;border:1px solid #d8e4eb!important;border-radius:12px!important;padding:8px!important;box-shadow:0 14px 35px #082f4326!important;z-index:1000!important}header .nav.open,.top .nav.open{display:flex!important}header .nav a,.top .nav a{display:block!important;padding:11px 12px!important;color:#082f43!important}.header-actions{margin-left:8px!important}.header-actions .login{display:none!important}header,.top{position:relative!important;z-index:100!important}.fixedbar,.bottom{font-size:11px}.fixedbar a{padding:10px 13px}.page-title{padding-top:28px}}';const MOBILE_JS='<script>(function(){document.querySelectorAll("header").forEach(function(h){var n=h.querySelector(".nav");if(!n||h.querySelector(".mobile-toggle"))return;var b=document.createElement("button");b.className="mobile-toggle";b.type="button";b.setAttribute("aria-label","메뉴 열기");b.textContent="☰";b.onclick=function(){n.classList.toggle("open");b.textContent=n.classList.contains("open")?"×":"☰"};var box=h.querySelector(".header-inner")||h.querySelector(".shell")||h;box.appendChild(b)});document.addEventListener("click",function(e){if(!e.target.closest("header"))document.querySelectorAll("header .nav.open").forEach(function(n){n.classList.remove("open")})})})();<\/script>';
const PHONE_CSS='.top-phone{display:inline-flex;align-items:center;gap:6px;margin-left:13px;padding:8px 12px;border:1px solid #cfe3ec;border-radius:10px;background:#eff9fc;color:#075374;font-size:12px;font-weight:900;white-space:nowrap}.top-phone i{font-style:normal;font-size:16px}.fixedbar .shell>div{display:flex;gap:10px}.fixedbar .limit-check{background:#0788b7;color:#fff;margin-left:0}@media(max-width:760px){.top-phone{margin-left:6px;padding:7px 8px;font-size:10px}.brand small{display:none!important}header .login{display:none!important}.fixedbar{padding:9px 8px}.fixedbar .shell{gap:8px}.fixedbar .shell>span{max-width:43%;line-height:1.35}.fixedbar .shell>div{gap:6px}.fixedbar .shell a{padding:9px 10px;white-space:nowrap}.fixedbar .limit-check{font-size:10px}}@media(max-width:560px){.fixedbar .shell>span{display:none}.fixedbar .shell>div{width:100%;display:grid;grid-template-columns:.8fr 1.2fr}.fixedbar .shell a{text-align:center;min-width:0}.top-phone span{font-size:0}.top-phone span:after{content:"전화상담";font-size:10px}}';
function enhance(body){let out=body.replaceAll("010-8393-2615","010-8692-0247").replaceAll("01083932615","01086920247");out=out.replaceAll('<a href="/corporate-card-payment/">법인카드대납</a>','<a href="/corporate-card-payment/">법인카드대납</a><a href="/card-limit-loan/">카드한도대출</a>').replace('<a href="/blog">블로그</a><a href="/login">로그인</a>','<a href="/blog">블로그</a><a href="/contact">문의하기</a><a href="/login">로그인</a>');if(!out.includes('class="phone-box"')&&!out.includes('class="top-phone"'))out=out.replace("</nav>",'</nav><a class="top-phone" href="tel:01086920247"><i>☎</i><span>전화상담 010-8692-0247</span></a>');if(out.includes("</nav>")&&!out.includes('class="bottom-bar"')&&!out.includes('class="bottom"')&&!out.includes('class="fixedbar"'))out=out.replace("</body>",'<div class="fixedbar"><div class="shell"><span>💡 신용카드 대납·법인카드대납 가능 조건을 확인하세요</span><div><a href="tel:01086920247">📞 전화상담</a><a class="limit-check" href="/#conditions">대출 한도·조건 확인 →</a></div></div></div></body>');out=out.replaceAll('>전화 상담</a>','>📞 전화상담</a>');return out}
function addSeo(body,canonical){const title=(body.match(/<title>([^<]*)<\/title>/i)||[])[1]||"돈트리대부중개";const description=(body.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)/i)||[])[1]||"신용카드 대납·법인카드대납 상담과 안전한 금융 정보를 안내합니다.";const existing=(body.match(/<link[^>]+rel=["']canonical["'][^>]+href=["']([^"']*)/i)||[])[1];const url=canonical||existing;if(!url)return body;let tags=existing?"":'<link rel="canonical" href="'+esc(url)+'">';tags+='<meta property="og:locale" content="ko_KR"><meta property="og:type" content="website"><meta property="og:site_name" content="돈트리대부중개"><meta property="og:title" content="'+esc(title)+'"><meta property="og:description" content="'+esc(description)+'"><meta property="og:url" content="'+esc(url)+'"><meta name="twitter:card" content="summary"><meta name="twitter:title" content="'+esc(title)+'"><meta name="twitter:description" content="'+esc(description)+'">';const schema={"@context":"https://schema.org","@type":"FinancialService",name:"돈트리대부중개",url:CANONICAL_ORIGIN,telephone:"010-8692-0247",email:"help@dontree.co.kr",address:{"@type":"PostalAddress",addressCountry:"KR",addressRegion:"인천광역시",addressLocality:"부평구",streetAddress:"대정로 66, 다운타운일레븐 408-143호"}};tags+='<script type="application/ld+json">'+JSON.stringify(schema).replace(/</g,"\\u003c")+'<\/script>';return body.replace("</head>",tags+"</head>")}
function html(body,status=200,cache=true,canonical=""){void cache;const out=addSeo(enhance(body),canonical).replace("</head>","<style>"+DETAIL_CSS+MOBILE_CSS+PHONE_CSS+"</style></head>").replace("</body>",MOBILE_JS+"</body>");return new Response(out,{status,headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff"}})}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function decorate(page){return page.replaceAll('href="#guide">블로그','href="/blog">블로그').replaceAll('href="#contact">문의하기','href="/contact">문의하기').replaceAll('href="tel:01083932615">문의하기','href="/contact">문의하기').replaceAll('class="login" href="#conditions"','class="login" href="/login"')}
function fieldValue(v){if(!v)return null;if("stringValue"in v)return v.stringValue;if("integerValue"in v)return Number(v.integerValue);if("timestampValue"in v)return v.timestampValue;if("nullValue"in v)return null;return null}
function parseDoc(row){const d=row.document;if(!d)return null;const out={id:d.name.split("/").pop()};for(const[k,v]of Object.entries(d.fields||{}))out[k]=fieldValue(v);return out}
function dateText(v){if(!v)return "";const d=new Date(v);return Number.isNaN(d.getTime())?"":new Intl.DateTimeFormat("ko-KR",{year:"numeric",month:"2-digit",day:"2-digit"}).format(d)}
function articleContent(value){return String(value||"").split(/\n+/).filter(Boolean).map(line=>{if(line.startsWith("## "))return '<h2 class="section-title">'+esc(line.slice(3))+'</h2>';if(line.startsWith("### "))return '<h3 class="section-subtitle">'+esc(line.slice(4))+'</h3>';if(line.startsWith("- "))return '<div class="article-point">✓ '+esc(line.slice(2))+'</div>';return '<p>'+esc(line)+'</p>'}).join("")}
async function publishedPosts(){const endpoint="https://firestore.googleapis.com/v1/projects/"+PROJECT_ID+"/databases/(default)/documents:runQuery?key="+API_KEY;const query={structuredQuery:{from:[{collectionId:"posts"}],where:{fieldFilter:{field:{fieldPath:"status"},op:"EQUAL",value:{stringValue:"published"}}},limit:100}};const res=await fetch(endpoint,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(query)});if(!res.ok)throw Error("Firestore "+res.status);return(await res.json()).map(parseDoc).filter(Boolean).sort((a,b)=>(b.postNumber||0)-(a.postNumber||0))}
function shell(title,description,body,canonical){return '<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+'</title><meta name="description" content="'+esc(description)+'">'+(canonical?'<link rel="canonical" href="'+canonical+'">':'')+'<style>'+CSS+'</style></head><body><header class="top"><div class="shell"><a class="brand" href="/">신용카드 대납·법인카드대납<small>정식 등록 대부중개 상담 안내</small></a><nav class="nav"><a href="/">홈</a><a href="/corporate-card-payment/">법인카드대납</a><a href="/blog">블로그</a><a href="/login">로그인</a></nav></div></header>'+body+'<footer class="footer"><div class="shell">돈트리대부중개　·　상담 010-8393-2615</div></footer><div class="fixedbar"><div class="shell"><span>💡 신용카드 대납·법인카드대납 가능 조건을 확인하세요</span><div><a href="tel:01083932615">📞 전화상담</a><a class="limit-check" href="/#conditions">대출 한도·조건 확인 →</a></div></div></div></body></html>'}
async function blogList(){try{const posts=await publishedPosts();const cats=[...new Set(posts.map(p=>p.category).filter(Boolean))];const items=posts.map((p,i)=>'<a class="blog-item" data-title="'+esc((p.title+" "+(p.summary||"")).toLowerCase())+'" data-category="'+esc(p.category||"금융 가이드")+'" href="/blog/'+p.postNumber+'">'+(p.imageUrl?'<img class="thumb" src="'+esc(p.imageUrl)+'" alt="'+esc(p.title)+'" loading="'+(i<3?'eager':'lazy')+'">':'<div class="thumb"></div>')+'<div class="card-copy"><div class="meta">● '+esc(p.category||"금융 가이드")+'</div><h2>'+esc(p.title)+'</h2><p>'+esc(p.summary||"자세한 내용을 확인하세요.")+'</p><div class="card-foot"><span>'+dateText(p.publishedAt)+'</span><span>조회 '+esc(p.viewCount||0)+'</span></div></div></a>').join("");const filters='<button class="cat active" data-cat="all">전체</button>'+cats.map(c=>'<button class="cat" data-cat="'+esc(c)+'">'+esc(c)+'</button>').join("");const script='<script>const q=document.getElementById("q"),cards=[...document.querySelectorAll(".blog-item")],cats=[...document.querySelectorAll(".cat")];let active="all";function run(){let s=q.value.trim().toLowerCase();cards.forEach(x=>x.hidden=!((active==="all"||x.dataset.category===active)&&(!s||x.dataset.title.includes(s))))}q.addEventListener("input",run);cats.forEach(b=>b.onclick=()=>{cats.forEach(x=>x.classList.remove("active"));b.classList.add("active");active=b.dataset.cat;run()});<\/script>';const body='<main class="shell"><div class="page-title"><h1>신용카드 대납·법인카드대납 금융 정보</h1><p class="muted">카드 결제, 사업자 금융, 신용관리와 안전한 대출 이용에 필요한 정보를 확인하세요.</p></div><div class="searchbox"><input id="q" type="search" placeholder="금융 정보를 검색하세요" aria-label="블로그 검색"><button type="button">검색</button></div><div class="blog-layout"><aside class="categories"><h2>카테고리</h2>'+filters+'</aside><section class="blog-list">'+(items||'<div class="panel empty">아직 공개된 글이 없습니다.</div>')+'</section></div><section class="cta"><h2>조건보다 중요한 것은 안전한 금융 확인입니다.</h2><p>등록 여부와 계약 조건을 확인한 뒤 상담을 진행하세요.</p><a href="tel:01083932615">무료 상담 신청</a></section></main>'+script;return html(shell("금융 정보 블로그 | 돈트리대부중개","신용카드 대납, 법인카드대납, 사업자 금융과 신용관리 정보를 안내합니다.",body,CANONICAL_ORIGIN+"/blog"))}catch(e){return html(shell("블로그 준비 중 | 돈트리대부중개","블로그를 준비하고 있습니다.",'<main class="shell"><div class="page-title"><h1>블로그</h1></div><div class="panel empty">Firestore 공개 읽기 규칙을 확인하세요.</div></main>'),503)}}
async function blogPost(n){try{const posts=await publishedPosts(),p=posts.find(x=>Number(x.postNumber)===Number(n));if(!p)return html(shell("글을 찾을 수 없습니다","요청한 게시글이 없습니다.",'<main class="shell"><div class="panel empty">요청한 글을 찾을 수 없습니다.</div></main>'),404);const canonical=CANONICAL_ORIGIN+"/blog/"+p.postNumber;const latest=posts.filter(x=>x.id!==p.id).slice(0,8).map(x=>'<a class="latest-item" href="/blog/'+x.postNumber+'">'+(x.imageUrl?'<img src="'+esc(x.imageUrl)+'" alt="">':'')+'<span><b>'+esc(x.title)+'</b><small>'+dateText(x.publishedAt)+'</small></span></a>').join("");const hero='<section class="detail-head"><div class="meta">'+esc(p.category||"금융 가이드")+' · '+dateText(p.publishedAt)+'</div><h1>'+esc(p.title)+'</h1><p>'+esc(p.summary||"")+'</p></section>';const article='<article class="panel article">'+(p.imageUrl?'<img class="article-hero" src="'+esc(p.imageUrl)+'" alt="'+esc(p.title)+'">':'')+'<div class="article-body">'+articleContent(p.content)+'</div><section class="article-cta"><b>안전한 금융 조건부터 확인하세요.</b><p>개인별 조건은 달라질 수 있으므로 충분히 비교한 뒤 결정하세요.</p><a href="tel:01083932615">전화 상담</a></section></article>';const sidebar='<aside class="latest"><h2>최신 글</h2>'+latest+'</aside>';const body='<main class="shell">'+hero+'<div class="detail-layout">'+article+sidebar+'</div><section class="cta"><h2>카드대금 부담, 합법적인 조건부터 확인하세요.</h2><p>등록 업체와 실제 계약 조건을 확인한 뒤 상담을 진행하세요.</p><a href="tel:01083932615">무료 상담 신청</a></section></main>';return html(shell(p.title+" | 돈트리대부중개",p.summary||p.title,body,canonical))}catch(e){return html(shell("게시글 오류","게시글을 불러오지 못했습니다.",'<main class="shell"><div class="panel empty">게시글을 불러오지 못했습니다.</div></main>'),503)}}
function json(data,status=200){return new Response(JSON.stringify(data),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store"}})}
async function adminFromToken(request){const auth=request.headers.get("authorization")||"";if(!auth.startsWith("Bearer "))return false;const res=await fetch("https://identitytoolkit.googleapis.com/v1/accounts:lookup?key="+API_KEY,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({idToken:auth.slice(7)})});if(!res.ok)return false;const data=await res.json();return(data.users?.[0]?.email||"").toLowerCase()==="cyber924@naver.com"}
function parseGenerated(text){let clean=String(text||"").trim().replace(/^```(?:json)?\s*/i,"").replace(/\s*```$/,"");const start=clean.indexOf("{"),end=clean.lastIndexOf("}");if(start>=0&&end>start)clean=clean.slice(start,end+1);const value=JSON.parse(clean);if(!value.title||!value.summary||!value.content)throw Error("필수 글 항목 누락");return value}
